document.querySelector("#batch38 .grid").insertAdjacentHTML("beforeend","<a class=\"card\" href=\"summaries/sallabi-40.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف عصر الدولة الزنكية\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">تاريخ · مجاني رسمي</span><h3>عصر الدولة الزنكية</h3><p>تضع المقدمة الأسرة الزنكية في سياق القوى المحلية والسلطنة السلجوقية والخلافة، ثم تتناول عماد الدين ونور الدين. وتعرض في خطتها اختيار الرجال والنظ…</p><small>علي محمد محمد الصلابي</small></a><a class=\"card\" href=\"summaries/sallabi-63.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف صلاح الدين الأيوبي وجهوده في القضاء على الدولة الفاطمية وتحرير بيت المقدس\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">تاريخ · مجاني رسمي</span><h3>صلاح الدين الأيوبي وجهوده في القضاء على الدولة الفاطمية وتحرير بيت المقدس</h3><p>تقدم المقدمة هذا الكتاب كحلقة تلي السلاجقة والزنكيين في مشروع المؤلف عن الحروب الصليبية. وتعود إلى جهود التوحيد السابقة قبل الوصول إلى صلاح الدين…</p><small>علي محمد محمد الصلابي</small></a><a class=\"card\" href=\"summaries/sallabi-32.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف الحملات الصليبية الرابعة والخامسة والسادسة والسابعة والأيوبيون بعد صلاح الدين\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">تاريخ · مجاني رسمي</span><h3>الحملات الصليبية الرابعة والخامسة والسادسة والسابعة والأيوبيون بعد صلاح الدين</h3><p>تعلن المقدمة أن العمل امتداد لكتب السلاجقة والزنكيين وصلاح الدين، ثم تضع النزاع بين خلفاء صلاح الدين في صدر خطتها. وتذكر الملك العادل والملك الكا…</p><small>علي محمد محمد الصلابي</small></a>");
